#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn the_qmf_banks_mirror_each_other() {
        // The high-band bank is the low-band one with every odd tap
        // negated -- the standard QMF relation. If the float arm had been
        // picked up under the same name this would not hold.
        for i in 0..64 {
            let want = if i % 2 == 0 { QMF_H0[i] } else { -QMF_H0[i] };
            assert_eq!(QMF_H1[i], want, "tap {i}");
        }
    }

    #[test]
    fn the_low_band_bank_is_symmetric() {
        // h0 is a linear-phase FIR, so it reads the same backwards.
        for i in 0..64 {
            assert_eq!(QMF_H0[i], QMF_H0[63 - i], "tap {i}");
        }
    }

    #[test]
    fn the_gain_ladders_are_monotonic() {
        assert!(OL_GAIN.windows(2).all(|w| w[0] < w[1]));
        assert!(GC_QUANT_BOUND.windows(2).all(|w| w[0] < w[1]));
        assert!(EXC_GAIN_SCAL3.windows(2).all(|w| w[0] < w[1]));
        assert!(EXC_GAIN_SCAL1.windows(2).all(|w| w[0] < w[1]));
    }

    #[test]
    fn the_pitch_codebook_is_128_entries_of_four() {
        assert_eq!(GAIN_CDBK_NB.len(), 4 * (1 << 7));
    }
}
